def doc(title,desc,body,path='',cls=''):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — Jorge Borloni</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#006554"><meta property="og:title" content="{e(title)} — Jorge Borloni"><meta property="og:description" content="{e(desc)}"><link rel="canonical" href="https://jorge-borloni-portfolio.jborloni.chatgpt.site/{path}"><link rel="stylesheet" href="/style.css?v=6"><link rel="stylesheet" href="/refinement.css?v=6"><link rel="icon" href="/favicon.svg" type="image/svg+xml"></head><body class="{cls}"><a class="skip" href="#conteudo">Pular para o conteúdo</a>{nav}{body}{footer}{dock(cls=="case-page")}<dialog class="image-dialog" aria-label="Imagem ampliada"><form method="dialog"><button aria-label="Fechar imagem">Fechar ×</button></form><img alt=""><p></p></dialog><script src="/script.js?v=6" defer></script></body></html>'''
