writing='''<section id="escritos" class="section writing"><div class="section-heading reveal"><div><p class="eyebrow">03 / IDEIAS QUE VIRARAM TEXTO</p><h2>Da minha cabeça<br>pro mundo.</h2></div><a class="text-link" href="https://medium.com/@jorge.borloni92">Todos no Medium ↗</a></div><a class="article-row reveal" href="https://medium.com/@jorge.borloni92/samba-e-design-o-que-tem-a-ver-84c9a383ca5b"><div class="article-thumb samba-thumb">'''+pandeiro+'''</div><div><span>CULTURA & DESIGN · 12 AGO. 2025</span><h3>Samba e Design,<br>o que tem a ver?</h3></div><span class="article-arrow">↗</span></a><a class="article-row reveal" href="https://medium.com/@jorge.borloni92/minha-jornada-dominando-desing-tokens-o-que-aprendi-9fa64908b897"><div class="article-thumb tokens-thumb"><i></i><i></i><i></i></div><div><span>DESIGN SYSTEMS · 18 MAI. 2025</span><h3>Minha jornada dominando<br>Design Tokens, o que aprendi?</h3></div><span class="article-arrow">↗</span></a></section>'''
